import os

# First, let's check what files are actually available
print("Checking available files in the system...")

# Check if /mnt/data exists
if not os.path.exists('/mnt/data'):
    print("/mnt/data directory does not exist")
    # Check parent directory
    if os.path.exists('/mnt'):
        print("Contents of /mnt:")
        try:
            print(os.listdir('/mnt'))
        except Exception as e:
            print(f"Error: {e}")
else:
    print("Contents of /mnt/data:")
    try:
        files = os.listdir('/mnt/data')
        for file in files:
            print(f"  {file}")
    except Exception as e:
        print(f"Error: {e}")

# Check current directory
print(f"\nCurrent working directory: {os.getcwd()}")
print("Files in current directory:")
try:
    current_files = os.listdir('.')
    for file in current_files[:20]:  # Show first 20 files
        print(f"  {file}")
    if len(current_files) > 20:
        print(f"  ... and {len(current_files) - 20} more files")
except Exception as e:
    print(f"Error: {e}")

# Look for database files in common locations
possible_db_paths = [
    '/mnt/data/customer360.db',
    './customer360.db',
    'customer360.db',
    '/mnt/data/database.db',
    './database.db'
]

print("\nChecking for database files...")
for db_path in possible_db_paths:
    if os.path.exists(db_path):
        print(f"✓ Found database at: {db_path}")
        print(f"  File size: {os.path.getsize(db_path)} bytes")
        break
else:
    print("✗ No database file found in common locations")

    # Search for any .db or .sqlite files
    print("\nSearching for any database files...")
    for root, dirs, files in os.walk('.'):
        for file in files:
            if file.endswith('.db') or file.endswith('.sqlite') or file.endswith('.sqlite3'):
                full_path = os.path.join(root, file)
                print(f"  Found: {full_path}")
